  var TIPS = {
    /* ── Blødningskontroll (X) ── */
    x_sikkerhet:      {name:"Egensikkerhet",plain:"Du er ressurs 1 – beskytt deg selv",body:"Vurder alltid fare før du nærmer deg:\n• Trafikk – stopp trafikk, bruk refleks\n• Brann / eksplosjon – hold avstand\n• Gass / kjemikalier – ikke gå inn\n• Aggresjon / vold – vent på politi\n• Ustabilt kjøretøy / ras\n\nEn skadet hjelper er en ekstra pasient.",sev:"d",rel:["blodning_stopp","hypotermi"]},
    piksib_tip:       {name:"PIKSIB",plain:"Lederverktøy for situasjonsstyring",body:"P – Planlegge\nI – Iverksette\nK – Kontrollere\nS – Støtte\nI – Informere\nB – Bedømme\n\nSyklisk prosess – ikke lineær. Brukes av teamleder.",sev:"",rel:[]},
    blodning_stopp:   {name:"Ukontrollert blødning",plain:"",body:"Arteriell blødning (pulserende, lys rød) dreper på minutter. Tiltak: direkte trykk minimum 10 minutter uten å slippe. Tourniquet ved ekstremitetsblødning. Wound packing ved lyske/armhule.",sev:"d",rel:["direkte_trykk","tourniquet_info","wound_packing","sjokk"]},
    direkte_trykk:    {name:"Direkte trykk",plain:"Trykk direkte mot blødningskilden",body:"Legg hånden (med hansker) direkte over såret og trykk hardt. Hold i minst 10 minutter uten å slippe for å sjekke. Bytt aldri bandasje – legg nytt oppå. Første valg ved alle blødninger.",sev:"d",rel:["tourniquet_info","wound_packing","blodning_stopp"]},
    tourniquet_info:  {name:"Tourniquet",plain:"Avsnøringsmansjett for å stoppe blødning",body:"Brukes ved ekstremitetsblødning som ikke stopper med direkte trykk. Legg så høyt på lemmet som mulig. Stram til blødning stopper – ikke bare til det strammer. Skriv tidspunkt. Fjern ikke i felt.",sev:"d",rel:["direkte_trykk","wound_packing","blodning_stopp"]},
    wound_packing:    {name:"Wound packing",plain:"Pakke sår med bandasje",body:"Brukes ved blødning fra lyske, armhule eller nakke der tourniquet ikke kan brukes. Pakk gasbind direkte inn i såret. Trykk kontinuerlig med knyttet hånd i minst 3 min (hemostatisk) eller 10 min (standard). Fjern aldri pakket materiale i felt.",sev:"d",rel:["direkte_trykk","tourniquet_info","sjokk"]},
    /* ── Luftvei (A) ── */
    luftvei:          {name:"Luftveisproblem",plain:"Pusten er truet",body:"Snorking = tungefall, gurgling = væske, stridor = obstruksjon. Kjevetak, sideleie, NPA. Alltid A før B.",sev:"d",rel:["luftveisoedem","inhalasjon","bevissth","agonalpust","kjevetak","npa","sideleie"]},
    luftvei_aapen:    {name:"Åpen luftvei",plain:"",body:"Pasienten snakker normalt og puster uten lyd. Ingen tiltak nødvendig nå, men monitor kontinuerlig.",sev:"",rel:["luftvei"]},
    fremmedlegeme:    {name:"Fremmedlegeme i luftvei",plain:"Noe blokkerer luftrøret",body:"Delvis blokkert (hoster, snakker): oppmuntre til kraftig hosting.\n\nFullstendig blokkert (kan ikke puste, snakke eller hoste):\n① 5 kraftige ryggslag mellom skulderbladene\n② 5 Heimlich-støt innover/oppover under navlen\n③ Veksle til fri luftvei eller bevisstløshet\n\nBevisstløs: start HLR – se etter fremmedlegeme i munn.",sev:"d",rel:["ryggslagg","heimlich","luftvei","hlr"]},
    snorking:         {name:"Snorking",plain:"Tungeroten faller bakover",body:"Snorkelyd under bevissthetspåvirkning skyldes at tungeroten faller bakover og blokkerer luftveien. Tiltak: kjevetak, sideleie, evt. NPA.",sev:"w",rel:["kjevetak","npa","sideleie","luftvei"]},
    gurgling:         {name:"Gurglelyd",plain:"Væske i luftveien",body:"Betyr blod, oppkast eller sekret i øvre luftveier. Tiltak: sideleie umiddelbart, suging hvis tilgjengelig. Aspirasjonfare er stor.",sev:"d",rel:["aspirasjon","sideleie","luftvei"]},
    stridor:          {name:"Stridor",plain:"Pipende innpust – delvis blokkert luftvei",body:"Høyfrekvent pipende lyd ved innpust tyder på delvis obstruksjon i øvre luftvei. Kan skyldes fremmedlegeme, ødem (anafylaksi, brannskade) eller traume mot strupen. Forverres raskt.",sev:"d",rel:["luftveisoedem","anafylaksi","luftveisskade","luftvei"]},
    kjevetak:         {name:"Kjevetak",plain:"Teknikk for å åpne luftveien",body:"Griper bak kjevevinkelen med begge hender og skyver underkjeven fremover. Brukes ved mistenkt nakkeskade da det ikke beveger nakken. Effektivt mot tungerotfall.",sev:"",rel:["npa","sideleie","cervikalcolumna","luftvei","hodeoverstrekning"]},
    hodeoverstrekning:{name:"Hodeoverstrekning",plain:"Tippe hodet bakover for å åpne luftvei",body:"Legg én hånd på pannen og tipp hodet forsiktig bakover mens du løfter haken opp med den andre hånden. Åpner luftveien ved tungerotfall.\n\nBRUKES IKKE ved mistenkt nakkeskade – bruk kjevetak i stedet.",sev:"",rel:["kjevetak","luftvei","cervikalcolumna"]},
    npa:              {name:"NPA – Nasopharyngeal airway",plain:"Myk tube gjennom nesen",body:"Myk gummikanyle som føres gjennom nesen for å holde luftveien åpen forbi tungeroten. Tolereres av semibevisste pasienter. Størrelse: 28F (kvinner) eller 32F (menn). Bruk rikelig med glidemiddel.",sev:"",rel:["kjevetak","luftvei","sideleie"]},
    sideleie:         {name:"Stabilt sideleie",plain:"Leie som beskytter luftveien",body:"Pasienten legges på siden. Forhindrer tungerotfall og aspirasjon. Alltid ved: bevisstløshet, rus, kramper, mistanke om oppkast. Kontraindikasjon: mistenkt spinalskade.",sev:"",rel:["kjevetak","luftvei","aspirasjon"]},
    suging:           {name:"Suging av luftvei",plain:"Fjerne blod eller sekret med sug",body:"Brukes ved gurgling for å fjerne blod, oppkast eller sekret fra munn og svelg.",sev:"",rel:["gurgling","luftvei"]},
    /* ── Pust (B) ── */
    hjelpemuskulatur: {name:"Hjelpemuskulatur",plain:"Ekstra muskler brukes ved anstrengt pust",body:"Normalt puster man kun med mellomgulvet. Ved pustevansker trekkes ekstra muskler inn: nakkemusklene (løfter skulderkammen ved innpust), mellomromsmuskler og bukmuskulatur. Synlig bruk er et tegn på alvorlig pustebesvær.",sev:"w",rel:["astma","pneumothorax","rf_kritisk","cyanose"]},
    brystbevegelse:   {name:"Brystbevegelse",plain:"Vurdering av respirasjonsbevegelse",body:"Se på brystet: beveger begge sider seg likt og symmetrisk? Asymmetri tyder på pneumothorax eller hemothorax. Paradoksal bevegelse (innover ved innpust) = flail chest. Legg hånden på brystet for å kjenne.",sev:"w",rel:["pneumothorax","hemothorax","ribbeinsbrudd"]},
    cyanose:          {name:"Cyanose",plain:"Blåfarge på lepper og fingre",body:"Blålig misfarging tyder på alvorlig oksygenmangel (SpO₂ vanligvis under 85%). Sentralcyanose (lepper) er mer alvorlig enn perifer cyanose (fingre). Alltid et alvorlig tegn.",sev:"d",rel:["hypoxi","spo2_kritisk","pneumothorax","hjertestans"]},
    rf_normal:        {name:"Respirasjonsfrekvens",plain:"Antall åndedrag per minutt",body:"Normal RF: 12–20/min hos voksen. Telles ved å observere brystbevegelse i 30 sekunder og gange med to.",sev:"",rel:["rf_kritisk","takypne","sjokk"]},
    rf_kritisk:       {name:"Kritisk respirasjonsfrekvens",plain:"Altfor sakte eller rask pust",body:"RF under 10/min = hypoventilasjon. Vanligst ved opiatoverdose eller dypt koma. RF over 29/min = alvorlig takypné. Begge krever umiddelbar handling.",sev:"d",rel:["respirasjonsdep","sjokk","astma","pneumothorax"]},
    spo2:             {name:"SpO₂ – oksygenmetning",plain:"Hvor mye oksygen blodet bærer",body:"Måles med pulsoksymeter. Normal: 95–100%. Under 90% = kritisk hypoksi. OBS: CO-forgiftning gir falskt normalt utslag!",sev:"",rel:["spo2_lav","spo2_kritisk","hypoxi","co"]},
    spo2_lav:         {name:"SpO₂ 90–94%",plain:"Nedsatt oksygenmetning",body:"Bekymringsfullt nivå. Sørg for åpen luftvei, gi oksygen hvis tilgjengelig.",sev:"w",rel:["spo2","hypoxi","pneumothorax","astma"]},
    spo2_kritisk:     {name:"SpO₂ under 90%",plain:"Kritisk lav oksygenmetning",body:"Livsfarlig hypoksi. Umiddelbar handling: luftvei, oksygen, ring 113.",sev:"d",rel:["spo2","hypoxi","luftvei"]},
    krepitasjon:      {name:"Krepitasjon",plain:"Knitrende lyd/følelse",body:"Ved ribbeinsbrudd: knitring ved palpasjon. Subkutant emfysem (luft under huden): bobleinnpakning-følelse rundt thoraxskader – tyder på pneumothorax.",sev:"w",rel:["ribbeinsbrudd","pneumothorax","thorax"]},
    apent_brystsar:   {name:"Åpent bryststår",plain:"Sår gjennom brystkassen",body:"Luft suges inn gjennom sårkanalen ved respirasjon. Behandling: vented chest seal. Blokkeres luften uten utveier kan spenningspneumothorax oppstå.",sev:"d",rel:["pneumothorax","hemothorax","tensjon"]},
    /* ── Sirkulasjon (C) ── */
    blek_klam_kald:   {name:"Blek, klam og kald hud",plain:"Klassiske sjokktegn i huden",body:"Blek: blod trekker bort fra huden for å prioritere vitale organer. Klam/svett: adrenalinrespons. Kald: redusert perifer blodsirkulasjon. Disse tre funnene sammen er sterk indikasjon på sjokk.",sev:"d",rel:["sjokk","kapillaerfyll","takykardi","hudstatus"]},
    leiring_blodning: {name:"Leiring ved blødning / sjokk",plain:"Korrekt posisjonering",body:"Standard sjokkleie: legg flat på ryggen, hev bena 20–30 cm (øker venøs retur til hjertet).\n\nUNNTAK – ikke hev bena ved:\n• Hodeskade (øker intrakranialt trykk)\n• Bekkenbrudd (smertefullt/farlig)\n• Hjerteproblem / lungeødem (sett halvoppreist)\n\nAlle: hold varm.",sev:"",rel:["sjokk","hypovolemi","hodeskade","bekken"]},
    puls_vurdering:   {name:"Pulsvurdering",plain:"Frekvens, styrke og regularitet",body:"Frekvens: normal 60–100/min. Styrke: kraftig (normal), svak/trådig (sjokk). Regularitet: regelmessig (normal), uregelmessig (arytmi).",sev:"",rel:["takykardi","bradykardi","arytmi","sjokk"]},
    hudstatus:        {name:"Hudstatus",plain:"Vurdering av hud som sirkulasjonsindikator",body:"Farge: blek (sjokk/anemi), grå/cyanotisk (hypoksi), rød/varm (infeksjon/distributivt sjokk). Temperatur: kald klam hud = sjokk.",sev:"",rel:["sjokk","kapillaerfyll","takykardi"]},
    kapillaerfyll:    {name:"Kapillærfyllingstid",plain:"Test for perifer sirkulasjon",body:"Trykk på fingertuppen i 5 sekunder, slipp og tell sekunder til fargen normaliseres. Normal: under 2 sekunder. Over 2 sek = nedsatt perifer sirkulasjon. Upålitelig i kulde.",sev:"",rel:["sjokk","hypovolemi","hudstatus"]},
    abdomen_distensjon:{name:"Abdominal distensjon",plain:"Oppblåst, spent mage",body:"Kan tyde på intern blødning, tarmperforasjon eller organruptur. Rigiditet (stiv mage) = peritoneal irritasjon = alvorlig.",sev:"d",rel:["miltruptur","leverruptur","tarmperf","sjokk"]},
    bekken_test:      {name:"Bekkenstabilitet – kun ett forsøk",plain:"",body:"Legg hender på begge hoftekammen og trykk forsiktig innover og nedover. Smerte eller bevegelse = bekkenfraktur. Gjenta ALDRI – forverrer blødning.",sev:"w",rel:["bekken","sjokk","hypovolemi"]},
    takykardi:        {name:"Takykardi",plain:"Rask puls over 100 slag/min",body:"Hjertet slår raskere enn normalt. Vanligste årsaker akutt: sjokk (kompensatorisk), smerte, frykt, feber, rus, hjertearytmi. Betablokkere kan maskere takykardi.",sev:"w",rel:["sjokk","arytmi","betablokkere"]},
    bradykardi:       {name:"Bradykardi",plain:"Langsom puls under 50 slag/min",body:"Årsaker: hjerteblokk, betablokkere, økt intrakranialt trykk (Cushing-respons), GHB/opiater, hypotermi. Alvorlig bradykardi under 40 kan gi besvimelse.",sev:"w",rel:["arytmi","hodeskade","hypotermi","gcs"]},
    hypotensjon:      {name:"Hypotensjon",plain:"Lavt blodtrykk under 90 mmHg systolisk",body:"Sent tegn på sjokk – kroppen har mistet kompensasjonsevnen. Behandle årsaken: stopp blødning, EpiPen ved anafylaksi, legg flat. Ikke vent på hypotensjon for å mistenke sjokk.",sev:"d",rel:["sjokk","hypovolemi","tamponade","tensjon"]},
    veneturgescens:   {name:"Veneturgescens",plain:"Oppblåste halsvener",body:"Tyder på økt trykk i det venøse systemet: hjertetamponade, tensjonspneumothorax, lungeembolus. Kombinert med hypotensjon = obstruktivt sjokk.",sev:"d",rel:["tamponade","tensjon","trombose","sjokk"]},
    trakealdeviasjon: {name:"Trakeal deviasjon",plain:"Luftrøret presses til siden",body:"Trakea presses bort fra affisert side ved tensjonspneumothorax. Er et sent og upålitelig tegn – handle på øvrige symptomer.",sev:"d",rel:["tensjon","pneumothorax"]},
    betablokkere:     {name:"Betablokkere",plain:"Hjertemedisin som demper pulsen",body:"Metoprolol, atenolol, bisoprolol. Begrenser hjertets evne til å øke pulsen. En pasient på betablokkere kan ha normal puls selv ved alvorlig sjokk eller blødning.",sev:"w",rel:["takykardi","sjokk","arytmi"]},
    /* ── D ── */
    nihss_tip:        {name:"NIHSS – Slag-skala",plain:"NIH Stroke Scale – alvorlighetsgrad 0–42",body:"0 = Normal\n1–4 = Mild\n5–15 = Moderat\n16–20 = Alvorlig\n21–42 = Svært alvorlig\n\nScore ≥5 = sannsynlig kandidat for trombolyse eller trombektomi på sykehus.",sev:"d",rel:["fast","bevissth","gcs"]},
    fast_f:           {name:"F – Face (ansiktshenge)",plain:"",body:"Be pasienten smile. Ved slag henger den ene munviken ned og ansiktet er asymmetrisk.",sev:"d",rel:["fast","fast_a","fast_s"]},
    fast_a:           {name:"A – Arms (armsvakhet)",plain:"",body:"Be pasienten løfte begge armer rett frem med lukkede øyne. Ved slag synker den ene armen ned.",sev:"d",rel:["fast","fast_f","fast_s"]},
    fast_s:           {name:"S – Speech (taleforstyrrelse)",plain:"",body:"Be pasienten si en setning. Utydelig tale, feil ord eller ingen tale = mulig slag.",sev:"d",rel:["fast","fast_f","fast_a"]},
    /* ── E ── */
    expose_klipp:     {name:"Klipp opp klærne",plain:"Aldri dra av – alltid klipp",body:"Bruk traumasaks. Dra aldri klær av ved mistanke om fraktur eller spinalskade. Dekk til raskt etter undersøkelse.",sev:"",rel:["hypotermi"]},
    expose_full:      {name:"Full eksponering",plain:"Hele kroppen fra hode til tå",body:"Inkludert rygg (loggroll). Du finner ikke skader du ikke ser etter. Spesielt viktig: lyske, bak knær, skalp, rygg.",sev:"",rel:["loggroll","hypotermi"]},
    basisfraktur:     {name:"Skallebasisbrudd",plain:"Brudd i skallens bunn",body:"Mistenkelig ved: blod eller klar væske fra øre/nese, blåmerker rundt øyne (brillehematom) eller bak øret (Battles sign). Tegner ofte forsinket.",sev:"d",rel:["hodeskade","intrakranialt","gcs"]},
    loggroll:         {name:"Loggroll",plain:"Teknikk for å snu pasient uten spinalrotasjon",body:"3–4 personer koordinerer for å snu pasienten i ett stykke. Leder styrer hodet. Brukes for å undersøke ryggen og legge på spinalbrett.",sev:"",rel:["columna","cervikalcolumna"]},
    spaceblanket:     {name:"Space blanket / redningsteppe",plain:"Foliepakket redningsteppe",body:"Reflekterer kroppens varme tilbake. Sølvsiden inn mot pasienten. Dekk hele kroppen inkludert hodet.",sev:"",rel:["hypotermi","isolering"]},
    isolering:        {name:"Isolasjon fra bakken",plain:"Forhindre varmetap til underlaget",body:"Bakken leder varme bort fra kroppen. Legg pasient på liggeunderlag, ryggsekk, greiner eller annet isolerende materiale.",sev:"",rel:["hypotermi","spaceblanket"]},
    /* ── Nødnumre ── */
    ring113:          {name:"113 – Ambulanse",plain:"",body:"Ring ved livstruende tilstand: hjertestans, bevistløshet, alvorlig skade, akutt brystsmerter, slag. AMK kan veilede deg underveis. Hold linjen åpen.",sev:"d",rel:[]},
    ring116117:       {name:"116 117 – Legevakt",plain:"",body:"Ring når du trenger legehjelp, men det ikke er livstruende. Åpent hele døgnet. Veiledning om du skal komme inn eller kan vente.",sev:"",rel:[]},
    ring02415:        {name:"02415 – Oppfølging av førstehjelpsytere",plain:"",body:"Norsk Luftambulanse tilbyr gratis og konfidensiell oppfølging til deg som har vært involvert i en krevende hendelse. Ring etter hjertestans, alvorlige ulykker eller hendelser som setter seg fast.",sev:"",rel:[]},
    ringGift:         {name:"22 59 13 00 – Giftinformasjonen",plain:"",body:"Norsk Giftinformasjon. Åpent 24/7. Ring ved mistanke om forgiftning, overdose eller uhell med kjemikalier. De kan gi råd om videre håndtering.",sev:"",rel:[]},
    /* ── SAMPLER ── */
    opqrst:           {name:"OPQRST",plain:"Strukturert smerteanamnese",body:"Onset: Når startet det? Plutselig eller gradvis?\nProvokasjon: Hva gjør det bedre/verre?\nKvalitet: Trykkende, stikkende, brennende?\nUtstråling: Stråler smerten et annet sted?\nStyrke: 0–10?\nTid: Hvor lenge?",sev:"",rel:["utstråling_hjerte","infarkt"]},
    allergi_med:      {name:"Medikamentallergi",plain:"",body:"Spesielt viktig: penicillin, NSAIDs (ibux), kontrastvæske. Allergiske reaksjoner varierer fra utslett til anafylaksi.",sev:"",rel:["anafylaksi"]},
    allergi_mat:      {name:"Matallergi",plain:"",body:"Vanligste: peanøtter, nøtter, fisk/skalldyr, melk, egg. Kan gi anafylaksi.",sev:"",rel:["anafylaksi"]},
    insulin_med:      {name:"Insulinbehandling",plain:"",body:"Pasienter på insulin kan få hypoglykemi ved: utilstrekkelig matinntak, uvanlig aktivitet, feil dose.",sev:"",rel:["hypoglykemi"]},
    siste_maltid:     {name:"Siste måltid",plain:"",body:"Relevant ved bevissthetspåvirkning (hypoglykemi?) og aspirasjonrisiko. Mat i magen øker aspirasjonsfaren.",sev:"",rel:["hypoglykemi","aspirasjon"]},
    hendelsesforlop:  {name:"Hendelsesforløp",plain:"",body:"Hva skjedde rett før? Aktivitet, posisjon. Er pasienten funnet eller bevitnet? Vitner gir avgjørende informasjon.",sev:"",rel:[]},
    aktivitet_debut:  {name:"Aktivitet ved debut",plain:"",body:"Brystsmerter ved hvile = mer alvorlig. Besvimelse under anstrengelse = mistenkelig for arytmi.",sev:"",rel:["infarkt","arytmi"]},
    risiko_royk:      {name:"Røyking",plain:"",body:"Sterk risikofaktor for hjerte-/karsykdom, KOLS og kreft.",sev:"",rel:["infarkt","fast"]},
    risiko_hjerte:    {name:"Hjertesykdom i familien",plain:"",body:"Familiær hjertesykdom (infarkt under 55 år hos nær slektning) øker risiko.",sev:"",rel:["infarkt","arytmi"]},
    risiko_alder:     {name:"Alder som risikofaktor",plain:"",body:"Eldre: økt risiko for hjerte-/karsykdom og fall. Under 35 år med hjertesymptomer: vurder medfødt hjertesykdom.",sev:"",rel:["hofte","infarkt","hjertestans"]},
    /* ── ISBAR ── */
    isbar_i:          {name:"I – Identify",plain:"",body:"Presentér deg med navn og rolle. Eks: «Hei, jeg heter Lars fra Røde Kors hjelpekorps.»",sev:"",rel:[]},
    isbar_s:          {name:"S – Situation",plain:"",body:"Pasientens alder/kjønn, hovedproblem og nøyaktig adresse/lokasjon.",sev:"",rel:[]},
    isbar_b:          {name:"B – Background",plain:"",body:"Hva skjedde, kjent sykehistorie, medisiner, tid siden hendelse.",sev:"",rel:[]},
    vitalia:          {name:"Vitale parametere",plain:"",body:"Gi konkrete tall: «Puls 118, svak. RF 22. SpO₂ 94%. GCS 8.» AMK gir bedre råd med konkrete tall.",sev:"",rel:["puls_vurdering","rf_normal","spo2","gcs"]},
    isbar_r:          {name:"R – Recommendation",plain:"",body:"Hva du ber om: hastegrad, traumeteam, helikopter. Spør om ETA.",sev:"",rel:[]},
    /* ── Normalverdier ── */
    puls_normal:      {name:"Normal puls: 60–100",plain:"",body:"Under 60 = bradykardi. Over 100 = takykardi. Atleter kan ha hvile-puls under 50 – normalt for dem.",sev:"",rel:["takykardi","bradykardi","arytmi"]},
    bt_normal:        {name:"Blodtrykk – normalt 100–140 mmHg",plain:"",body:"Systolisk BT under 90 = hypotensjon = sjokk inntil annet bevist. Relativ hypotensjon (fall fra basislinje) kan være viktigere enn absolutt verdi.",sev:"",rel:["hypotensjon","sjokk","hypovolemi"]},
    temp_normal:      {name:"Normal temperatur 36,5–37,5°C",plain:"",body:"Under 35°C = hypotermi. Over 38°C = feber. Over 40°C med CNS-påvirkning = varmeslag.",sev:"",rel:["hypotermi","varmeslag"]},
    bs_normal:        {name:"Normalt blodsukker 4–7 mmol/L",plain:"",body:"Under 4 mmol/L = hypoglykemi. Over 14 = høyt. Mål alltid ved bevissthetspåvirkning.",sev:"",rel:["hypoglykemi"]},
    avpu_a:           {name:"A – Alert",plain:"Våken og orientert",body:"Pasienten er våken, reagerer spontant og er orientert for sted, tid og person.",sev:"",rel:["avpu_v","gcs"]},
    avpu_v:           {name:"V – Voice",plain:"Reagerer på stemme",body:"Reagerer på tiltale, men ikke spontant våken. Tilsvarer GCS 9–12.",sev:"w",rel:["avpu_a","avpu_p","gcs","bevissth"]},
    avpu_p:           {name:"P – Pain",plain:"Reagerer kun på smertestimulus",body:"Tilsvarer GCS 5–8. Alvorlig – sikre luftvei, ring 113.",sev:"d",rel:["avpu_v","avpu_u","gcs","luftvei"]},
    avpu_u:           {name:"U – Unresponsive",plain:"Ingen respons",body:"Ingen reaksjon på stemme eller smerte. GCS 3–4. Kritisk – umiddelbar luftvei og HLR-vurdering.",sev:"d",rel:["avpu_p","gcs","hjertestans","luftvei"]},
    gcs_normal:       {name:"GCS 15 – normal",plain:"Full bevissthet",body:"Øyne åpnes spontant (4), orientert verbal respons (5), følger motoriske kommandoer (6).",sev:"",rel:["gcs","avpu"]},
    gcs_paavirket:    {name:"GCS 13–14 – lett påvirket",plain:"",body:"Liten svikt i orientering eller motorisk respons. Følg nøye – kan raskt forverres.",sev:"w",rel:["gcs","hodeskade","hypoglykemi"]},
    gcs_alvorlig:     {name:"GCS 8 eller under – alvorlig",plain:"",body:"Grensen for alvorlig hodeskade. Luftvei i fare – kan ikke beskytte den selv. Vurder NPA. Ring 113.",sev:"d",rel:["gcs","luftvei","npa","hodeskade"]},
    /* ── Medisinske tilstander ── */
    utstråling_hjerte:{name:"Smerteutstråling ved hjerteinfarkt",plain:"",body:"Klassisk: trykkende brystsmerter til venstre arm, kjeve, nakke eller rygg. Atypisk (kvinner/eldre/diabetikere): kvalme, dyspné, tretthet – uten brystsmerter.",sev:"d",rel:["infarkt","fast"]},
    infarkt_tegn:     {name:"Tegn på hjerteinfarkt",plain:"",body:"Svette, kvalme, dyspné, blek hud. Klamsvette er karakteristisk.",sev:"d",rel:["infarkt","sjokk","arytmi"]},
    epipen:           {name:"EpiPen – adrenalinpenn",plain:"",body:"Injiseres i ytre lår (kan gå gjennom klær). Dose: 0,3 mg (voksen), 0,15 mg (barn under 25 kg). Trekk av sikring, trykk mot lår, hold 10 sek.",sev:"d",rel:["anafylaksi","luftveisoedem","sjokk"]},
    astma_alvorlig:   {name:"Alvorlig astmaanfall",plain:"",body:"Kan ikke snakke setninger, puls over 110, RF over 25, cyanose. Bronkodilator, oksygen, ring 113.",sev:"d",rel:["astma","luftvei","spo2_kritisk"]},
    astma_kritisk:    {name:"Stille thorax – kritisk astma",plain:"",body:"Ingen hvesing lenger = ingen luft passerer = nær respirasjonsstans. Umiddelbar AMK.",sev:"d",rel:["astma_alvorlig","respirasjonsdep","hjertestans"]},
    hypoglykemi_bevisstlos:{name:"Bevisstløs ved hypoglykemi",plain:"",body:"Legg i stabilt sideleie. Ring 113. Gi aldri noe oralt – aspirasjonfare.",sev:"d",rel:["hypoglykemi","sideleie","aspirasjon"]},
    ikke_oralt:       {name:"Aldri gi noe oralt til bevisstløs",plain:"",body:"En bevisstløs pasient mangler svelgerefleks. Mat, drikke eller tabletter kan aspireres.",sev:"d",rel:["aspirasjon","sideleie"]},
    /* ── Rus ── */
    alkohol_tale:     {name:"Utydelig tale ved alkohol",plain:"",body:"Alkohol demper CNS og gir slørete tale. Kan forveksles med slag eller hodeskade. Vurder FAST ved usikkerhet.",sev:"w",rel:["alkohol","fast","hodeskade"]},
    hallusinasjon:    {name:"Hallusinasjon",plain:"Sanseopplevelse uten ytre stimulus",body:"Kan se, høre eller kjenne ting som ikke er der. Rolig trygt miljø, talk-down. Ring 113 ved aggresjon eller bevisstløshet.",sev:"w",rel:["vidpupiller","desorientering","talkdown"]},
    desorientering:   {name:"Desorientering",plain:"Forvirring om tid, sted eller person",body:"Vanlig ved rus, hodeskade, hypoglykemi, demens. Vurder alltid medisinsk årsak.",sev:"w",rel:["bevissth","hodeskade","hypoglykemi","hallusinasjon"]},
    talkdown:         {name:"Talk-down teknikk",plain:"Verbal beroligelse",body:"Snakk rolig og tydelig. Unngå skarpe lyder, sterkt lys. Minimer antall folk. Si hvem du er og at du er der for å hjelpe.",sev:"",rel:["hallusinasjon","desorientering"]},
    sedasjon:         {name:"Sedasjon / sløvhet",plain:"",body:"Unormalt nedsatt aktivitetsnivå. Observér nøye – kan utvikle seg til bevisstløshet.",sev:"w",rel:["bevissth","respirasjonsdep","avpu_v"]},
    amnesi:           {name:"Amnesi / hukommelsestap",plain:"",body:"Vanlig etter benzodiazepiner, alkohol og GHB. Vurder alltid hodeskade.",sev:"w",rel:["hodeskade","hjernerystelse","alkohol"]},
    benzo_alkohol:    {name:"Benzo + alkohol",plain:"Livsfarlig kombinasjon",body:"Begge demper CNS og respirasjon. Kombinert effekt er kraftig forsterket. En av de vanligste dødelige overdosekombinasjonene.",sev:"d",rel:["respirasjonsdep","luftvei","sideleie"]},
    ghb_vaakne:       {name:"GHB – brått oppvåkning",plain:"",body:"Etter 1–4 timer kan pasienten våkne brått fra bevisstløshet, desorientert og agitert. Hold avstand.",sev:"w",rel:["ghb","desorientering"]},
    psykose:          {name:"Akutt psykose",plain:"",body:"Tap av kontakt med virkeligheten. Kan utløses av syntetisk cannabis, amfetamin. Ring 113 ved aggressiv atferd.",sev:"w",rel:["hallusinasjon","stimulanter","bevissth"]},
    rode_oyne:        {name:"Røde øyne",plain:"",body:"Konjunktival injeksjon (rødhet i øynene) er et klassisk tegn på cannabisrus.",sev:"",rel:["cannabis_rus"]},
    cannabis_rus:     {name:"Cannabispåvirkning",plain:"",body:"Latter, eufori, tørr munn, økt appetitt, paranoia, røde øyne. Vanligvis ikke medisinsk farlig i seg selv.",sev:"",rel:["psykose","rode_oyne","vidpupiller"]},
    kvalme_oppkast:   {name:"Kvalme og oppkast",plain:"",body:"Aspirasjonfare ved nedsatt bevissthet – sideleie umiddelbart. Kraftig/repetert oppkast kan tyde på intrakranialt trykk eller forgiftning.",sev:"w",rel:["sideleie","aspirasjon","hodeskade","ghb"]},
    /* ── Skader ── */
    lyske:            {name:"Lyske / hamstringskade",plain:"",body:"Akutt smerte ved sprint eller spark. Hvile, is, kompresjon.",sev:"w",rel:["femur"]},
    multippeltraume:  {name:"Multippeltraume",plain:"Skade på flere organsystemer",body:"Krever systematisk ABCDE og tidlig AMK. Transportbeslutning er kritisk.",sev:"d",rel:["sjokk","hodeskade","thorax"]},
    ansiktsfraktur:   {name:"Ansiktsfraktur",plain:"",body:"Vurder luftvei – blødning kan true den. Øyeskade: dekk med skål, ikke trykk.",sev:"w",rel:["luftvei","hodeskade"]},
    hodepine:         {name:"Hodepine etter traume",plain:"",body:"Vedvarende eller forverrende hodepine er alvorlig og kan tyde på intrakranialt hematom.",sev:"w",rel:["hjernerystelse","intrakranialt","hodeskade"]},
    lysoemt:          {name:"Lysømfintlighet (fotofobi)",plain:"",body:"Vondt av lys. Vanlig ved hjernerystelse og meningitt. Indikerer CNS-irritasjon.",sev:"w",rel:["hjernerystelse","hodeskade"]},
    uttomming:        {name:"Uttømming / utmattelse",plain:"",body:"Glykogenlagre tømt. Symptomer: ekstrem slapphet, forvirring. Gi mat/drikke med sukker.",sev:"w",rel:["hypoglykemi","varmeslag","dehydrering"]},
    luftror:          {name:"Luftrørsskade",plain:"",body:"Skade på trakea kan gi stridor og cyanose. Alvorlig og raskt forverrende.",sev:"d",rel:["luftvei","luftveisskade","krepitasjon"]},
    spiseror:         {name:"Spiserørsskade",plain:"",body:"Sjelden. Kan gi mediastinitt over timer–dager. Mistenkelig ved nakke-stikk med svelgvansker.",sev:"w",rel:["tarmperf"]},
    barn_kompenserer: {name:"Barn kompenserer lenge",plain:"",body:"Barn har god fysiologisk reserve og kan opprettholde normalt BT og bevissthet selv ved alvorlig sjokk. Kollapsen kommer brått.",sev:"d",rel:["hodeskade","sjokk","lungekont"]},
    triage_gul:       {name:"Gul triage – utsettbar",plain:"",body:"Skadet men stabil. Kan vente til røde er behandlet. Overvåk tett.",sev:"w",rel:["sjokk","blodning_kontrollert"]},
    triage_gronn:     {name:"Grønn triage – lettere skadet",plain:"",body:"Gangbar med lettere skader. Samle på et felles område.",sev:"",rel:[]},
    triage_sort:      {name:"Svart triage – ikke prioriter",plain:"",body:"Ingen puls og ingen åndedrett, eller skade som ikke er overlevbar gitt tilgjengelige ressurser.",sev:"",rel:[]},
    blodning_kontrollert:{name:"Kontrollert blødning",plain:"",body:"Blødningen er stoppet eller under kontroll. Overvåk – kan igjen bli ukontrollert.",sev:"w",rel:["sjokk","hypovolemi"]},
    puls_distalt:     {name:"Puls distalt for skade",plain:"",body:"Etter ekstremitetsskade: sjekk puls distalt. Fraværende puls = karskade – øyeblikkelig tiltak og transport.",sev:"d",rel:["deformitet","compartment","femur","tibia"]},
    deformitet:       {name:"Deformitet / hevelse",plain:"",body:"Tyder på fraktur eller dislokasjon. Vurder puls og sensibilitet distalt. Stabiliser i funnet stilling.",sev:"w",rel:["femur","tibia","ankel","kne"]},
    /* ── Hoved-TIPS (beholdes fra tidligere) ── */
    hodeskade:        {name:"Hodeskade",plain:"Skade på hjerne eller kranium",body:"Kan gi bevissthetspåvirkning, hukommelsestap, forvirring, oppkast og ulik pupillstørrelse. Vurder alltid GCS. Mistenk alltid ved relevant MOI.",sev:"d",rel:["gcs","avpu","pupiller","hjernerystelse","intrakranialt","subduralt"]},
    cervikalcolumna:  {name:"Cervikalcolumna",plain:"Nakkevirvelkolumnen (C1–C7)",body:"De 7 nakkevirvlene som beskytter ryggmargen. Skade kan gi lammelse fra skuldrene og ned. Stabiliser alltid ved relevant MOI.",sev:"d",rel:["columna","hodeskade","kjevetak"]},
    thorax:           {name:"Thorax",plain:"Brystkassen",body:"Inneholder lunger, hjerte og store kar. Skader kan gi pneumothorax, hemothorax eller aortaskade. Vurder symmetrisk pustelyd.",sev:"w",rel:["pneumothorax","hemothorax","hjerteskade","aorta","ribbeinsbrudd","tensjon"]},
    pneumothorax:     {name:"Pneumothorax",plain:"Sammenfallt lunge",body:"Luft lekker inn mellom lunge og brystvegg. Tegn: ensidig svekket pustelyd, dyspné.\n\nNåldekompresjonen:\n① 2. IKR, midklavikulærlinje (over 3. ribbein)\n② 4.–5. IKR, fremre aksillærlinje\n\nBruk 14G nål, minst 8 cm. Stikk over ribbeinkanten.",sev:"d",rel:["hemothorax","tensjon","blastlung","ribbeinsbrudd"]},
    hemothorax:       {name:"Hemothorax",plain:"Blod i brysthule",body:"Blod samler seg mellom lunge og brystvegg. Dempet perkusjon. Kan gi respirasjonssvikt og sjokk. Krever dren på sykehus.",sev:"d",rel:["pneumothorax","sjokk","thorax"]},
    milt:             {name:"Miltskade",plain:"Milten kan sprekke",body:"Sitter øverst til venstre i buken. Svært blødningsvillig. Kan rupturere forsinket.",sev:"d",rel:["miltruptur","sjokk","leverruptur"]},
    miltruptur:       {name:"Miltruptur",plain:"Milten sprekker",body:"Gir intern blødning i buken. Forsinket debut er vanlig – stabil 30–60 min, så rask forverring.",sev:"d",rel:["sjokk","leverruptur","hypovolemi"]},
    leverruptur:      {name:"Leverruptur",plain:"Leveren sprekker",body:"Sitter øverst til høyre i buken. Svært blødningsvillig. Vanlig ved styretraume og høyenergi-kollisjon.",sev:"d",rel:["miltruptur","sjokk","hypovolemi"]},
    aorta:            {name:"Aortaskade",plain:"Skade på kroppens hovedpulsåre",body:"Ruptur eller disseksjon er raskt dødelig. Mistenk ved høyenergi frontkollisjon eller fall.",sev:"d",rel:["sjokk","hypovolemi","tamponade"]},
    bekken:           {name:"Bekkenfraktur",plain:"Brudd i bekkenet",body:"Kan blø svært mye internt – opptil 3–4 liter. Livstruende sjokk uten synlig blødning.",sev:"w",rel:["sjokk","hypovolemi","femur"]},
    femur:            {name:"Femurfraktur",plain:"Brudd i lårbenet",body:"Kan gi 1–2 liter internt blodtap. Deformitet og hevelse i låret.",sev:"w",rel:["bekken","sjokk","tibia"]},
    tibia:            {name:"Tibia",plain:"Skinnebenet",body:"Vanlig ved direkte slag. Åpne brudd gir infeksjonsrisiko. Sjekk puls og sensibilitet distalt.",sev:"",rel:["femur","ankel","compartment"]},
    columna:          {name:"Columna",plain:"Ryggraden",body:"Beskytter ryggmargen. Skade kan gi lammelse. Stabiliser i nøytral posisjon ved mistanke.",sev:"d",rel:["cervikalcolumna","calcaneus","bekken"]},
    calcaneus:        {name:"Calcaneus",plain:"Hælbenet",body:"Brekker ved aksial belastning. Kombinert med lumbale frakturer og bekkenskader.",sev:"d",rel:["columna","bekken","femur"]},
    subduralt:        {name:"Subduralt hematom",plain:"Blodansamling under hjernehinna",body:"Forsinket bevissthetspåvirkning timer etter skaden. Særlig risiko hos eldre og de som bruker blodfortynnende.",sev:"d",rel:["hodeskade","intrakranialt","antikoag","gcs"]},
    intrakranialt:    {name:"Intrakranialt hematom",plain:"Blodansamling inne i skallen",body:"Økt trykk gir hodepine, oppkast og bevissthetspåvirkning. Ensidig vid pupill er et alvorlig tegn.",sev:"d",rel:["hodeskade","subduralt","pupiller","gcs"]},
    acl:              {name:"ACL/MCL-skade",plain:"Korsband / sidebånd i kneet",body:"Typisk ved vridning eller takling. Hørt smell + hevelse + ustabilt kne.",sev:"w",rel:["kne","ankel","akillesruptur"]},
    skulder:          {name:"Skulder­skade",plain:"Skulder",body:"Dislokasjon, AC-leddskade eller klavikkelbrudd. Dislokasjon gir tydelig deformitet.",sev:"w",rel:["klavikkel","handledd"]},
    klavikkel:        {name:"Klavikkelbrudd",plain:"Kragebensbrudd",body:"Det mest brutte beinet i kroppen. Typisk ved fall på skulder eller OTB.",sev:"",rel:["skulder","handledd"]},
    handledd:         {name:"Håndleddsskade",plain:"Håndledd",body:"Colles-fraktur ved fall på utstrakt hånd. Sjekk puls og sensibilitet distalt.",sev:"",rel:["skulder","klavikkel"]},
    ankel:            {name:"Ankelskade",plain:"Ankel",body:"Ottawa-reglene: ømhet over malleol + ikke bæreevne = røntgen.",sev:"",rel:["tibia","kne","acl"]},
    kne:              {name:"Kneskade",plain:"Kne",body:"ACL, menisk eller patellafraktur. Rask hevelse tyder på blod i leddet.",sev:"",rel:["acl","ankel","akillesruptur"]},
    akillesruptur:    {name:"Akillesruptur",plain:"Akillessenen ryker",body:"Hørbart smell + kollaps. Kan ikke stå på tå. Thompson-test: klem på legg – foten beveger seg ikke.",sev:"d",rel:["acl","kne"]},
    hjertestans:      {name:"Hjertestans",plain:"Hjertet slutter å pumpe",body:"Ingen puls, ingen pusting. Start HLR umiddelbart. AED så raskt som mulig.",sev:"d",rel:["hlr","aed","arytmi","agonalpust","tamponade","tensjon","trombose","hypoxi","hypovolemi"]},
    arytmi:           {name:"Arytmi",plain:"Uregelmessig hjerterytme",body:"Kan gi svimmelhet, besvimelse eller plutselig hjertestans.",sev:"w",rel:["hjertestans","hypotermi","hypokalemi","tamponade"]},
    hypotermi:        {name:"Hypotermi",plain:"Farlig nedkjøling",body:"Under 35°C. Mild: skjelving. Moderat: forvirring. Alvorlig: bevisstløshet. Fjern våte klær, isoler.",sev:"d",rel:["arytmi","koagulopati","sjokk"]},
    hypoglykemi:      {name:"Hypoglykemi",plain:"For lavt blodsukker",body:"Under 4 mmol/L. Svette, skjelving, forvirring, aggresjon, bevisstløshet. Ligner rus og hodeskade. Mål alltid blodsukker ved bevissthetspåvirkning.",sev:"d",rel:["bevissth","synkope","varmeslag"]},
    varmeslag:        {name:"Varmeslag",plain:"Farlig overoppheting",body:"Over 40°C med CNS-påvirkning. Varm tørr hud + forvirring. Avkjøl aktivt.",sev:"d",rel:["hypoglykemi","dehydrering","bevissth"]},
    hyponatremi:      {name:"Hyponatremi",plain:"For lavt natrium i blodet",body:"Overdreven vanninntak under løp. Kvalme, hodepine, forvirring, kramper. Ikke gi mer vann.",sev:"d",rel:["dehydrering","hypoglykemi","bevissth"]},
    hjernerystelse:   {name:"Hjernerystelse",plain:"Hjernen rystes",body:"Forvirring, amnesi, hodepine, kvalme. Ikke tilbake til aktivitet samme dag – risiko for second impact syndrome.",sev:"d",rel:["hodeskade","intrakranialt","subduralt","gcs"]},
    synkope:          {name:"Vasovagal synkope",plain:"Vanlig besvimelse",body:"Utløses av smerte, stress, varme eller langvarig stående. Legg flat, hev bena.",sev:"",rel:["hypoglykemi","arytmi","dehydrering"]},
    overdose:         {name:"Rus / overdose",plain:"For mye rusmidler",body:"Opiater: langsom pusting, små pupiller, bevisstløshet. Alltid luftvei og sideleie.",sev:"d",rel:["respirasjonsdep","bevissth","luftvei","hypoglykemi"]},
    respirasjonsdep:  {name:"Respirasjonsdepresjon",plain:"Pustingen hemmes",body:"Pustefrekvens under 10/min. Vanligst ved opiatrus. Behandling: luftvei, oksygen.",sev:"d",rel:["overdose","luftvei","bevissth"]},
    epilepsi:         {name:"Epileptisk anfall",plain:"Kramper",body:"Beskytt mot skader. Anfallet går som regel over av seg selv. Ring 113 ved anfall over 5 min.",sev:"w",rel:["bevissth","hypoglykemi","hodeskade"]},
    crowdcrush:       {name:"Crowd crush",plain:"Mengdetrykk mot brystet",body:"Kan stoppe pusteevnen selv i stående stilling. Frigjøring er behandlingen.",sev:"d",rel:["thorax","ribbeinsbrudd","sjokk","trampling"]},
    trampling:        {name:"Trampling",plain:"Tråkket ned av folkemasse",body:"Kan gi multippelt traume og hodeskader.",sev:"d",rel:["hodeskade","thorax","crowdcrush"]},
    crush:            {name:"Crush-skade",plain:"Klemskade fra tung gjenstand",body:"Vev og organer knuses. Langvarig klem = risiko for rabdomyolyse og nyresvikt ved frigjøring.",sev:"d",rel:["rabdomyolyse","compartment","sjokk"]},
    blastlung:        {name:"Blast lung",plain:"Lungeblødning fra trykkbølge",body:"Gir lungeblødning uten ytre tegn. Dyspné, blod i oppspytt, hypoksi.",sev:"d",rel:["pneumothorax","hemothorax","hypoxi","tympanisk"]},
    tympanisk:        {name:"Tympanisk membranruptur",plain:"Trommehinnen sprekker",body:"Markør for primærblast-eksponering. Hørselstap og øresmerter.",sev:"w",rel:["blastlung"]},
    co:               {name:"CO-forgiftning",plain:"Karbonmonoksid – luktfri gass",body:"Gir hypoksi uten cyanose. Hodepine, kvalme, forvirring. Pulsoksymeter viser FALSKT normalt!",sev:"d",rel:["hypoxi","bevissth","inhalasjon"]},
    inhalasjon:       {name:"Inhalasjonsskade",plain:"Skade fra røyk/varme",body:"Varm luft og giftige gasser kan brenne luftveiene. Forsinket ødem kan lukke luftveien timer etter.",sev:"d",rel:["luftveisoedem","luftvei","co","brannskade"]},
    luftveisoedem:    {name:"Luftveisødem",plain:"Hevelse i luftveiene",body:"Stridor og heshet = handle nå. Kan lukke seg fullstendig.",sev:"d",rel:["inhalasjon","luftvei","anafylaksi"]},
    brannskade:       {name:"Brannskade",plain:"Forbrenningsskade",body:"Grad 1: rødhet. Grad 2: blemmer. Grad 3: dyp hudskade. Kjøl med romtemperert vann 20 min. Ikke is.",sev:"w",rel:["inhalasjon","luftveisoedem","co","hypotermi"]},
    impalement:       {name:"Impalement",plain:"Gjennomboret av en gjenstand",body:"ALDRI fjern gjenstanden i felt. Stabiliser mekanisk og transport til sykehus.",sev:"d",rel:["tarmperf","aorta","hjerteskade"]},
    karotis:          {name:"Karotis / jugular",plain:"Halspulsåre / halsblodåre",body:"Store kar i nakken. Direkte trykk umiddelbart ved stikk.",sev:"d",rel:["sjokk","luftveisskade","hypovolemi"]},
    luftveisskade:    {name:"Luftveisskade",plain:"Skade på luftrøret eller strupen",body:"Slag mot nakken kan skade strupen. Stridor kan gi raskt lukket luftvei.",sev:"d",rel:["luftveisoedem","luftvei","karotis"]},
    hjerteskade:      {name:"Hjerteskade",plain:"Skade på selve hjertemuskelen",body:"Penetrerende mot midtre thorax. Becks triade: hypotensjon + distenderte halsvener + dempede hjertelyder.",sev:"d",rel:["tamponade","aorta","sjokk"]},
    tarmperf:         {name:"Tarmperforasjon",plain:"Hull i tarmen",body:"Gir peritonitt. Kan ikke behandles i felt. Rask transport.",sev:"d",rel:["milt","leverruptur","aorta"]},
    hofte:            {name:"Hoftebrudd",plain:"Brudd i øvre del av lårbenet",body:"Typisk hos eldre ved lavenergi-fall. Kan gi livstruende blødning.",sev:"d",rel:["sjokk","bekken","antikoag"]},
    abruptio:         {name:"Abruptio placentae",plain:"Morkaken løsner",body:"Løsner ved stumpt abdominaltraume. Livstruende for foster og mor.",sev:"d",rel:["aortokavalt","sjokk","hypovolemi"]},
    aortokavalt:      {name:"Aortokavalt kompr.",plain:"Livmoren klemmer store blodårer",body:"Livmoren i ryggeleie trykker på aorta og vena cava. Legg gravide på venstre side ved >20 ukers graviditet.",sev:"w",rel:["abruptio","sjokk"]},
    antikoag:         {name:"Blodfortynnende",plain:"Antikoagulantia øker blødningsrisiko",body:"Tre hovedkategorier:\n• Vitamin K-antagonister (warfarin-type)\n• Direktevirkende orale antikoagulantia (DOAK)\n• Hepariner (injeksjon)\n\nAlle øker blødningsrisikoen kraftig. Spesielt viktig ved hodeskade og indre blødning – subduralt hematom kan oppstå ved minimalt traume.",sev:"w",rel:["subduralt","hofte","sjokk"]},
    antikoag_doak:    {name:"DOAK – direktevirkende antikoagulantia",plain:"Moderne blodfortynnende",body:"Direktevirkende orale antikoagulantia (DOAK) brukes i stedet for warfarin hos mange pasienter. Viktig å vite om ved blødning og hodeskade – øker blødningsrisikoen.\n\nSpørsmålet er om pasienten tar blodfortynnende, ikke hvilket preparat.",sev:"w",rel:["antikoag","subduralt","sjokk"]},
    lungekont:        {name:"Lungekontusjon",plain:"Blåmerke på lungen",body:"Lungen blør innvendig. Hos barn: ribben bøyelige, men kraften overføres til lungen.",sev:"w",rel:["pneumothorax","hemothorax","thorax","ribbeinsbrudd"]},
    dehydrering:      {name:"Dehydrering",plain:"Kroppen mangler væske",body:"Tørr munn, mørk urin, svimmelhet. Eldre er spesielt sårbare.",sev:"w",rel:["hyponatremi","sjokk","hypoglykemi"]},
    skipolletommel:   {name:"Skipolletommel (UCL)",plain:"Leddbåndet i tommelens rotledd",body:"UCL ryker ved fall med skistav i hånden. Instabilt tommelgrep.",sev:"i",rel:["handledd"]},
    frostskader:      {name:"Frostskader",plain:"Vevet er frosset",body:"Grad 1: rødhet. Grad 2: blemmer. Grad 3: nekrose. Ikke gni. Varm forsiktig.",sev:"w",rel:["hypotermi"]},
    sjokk:            {name:"Sjokk",plain:"Utilstrekkelig blodforsyning til organer",body:"Organer får ikke nok oksygenrikt blod.\n\nTidlige tegn (kompensert):\n• Takykardi – rask puls (>100)\n• Blek, klam og kald hud\n• Kapillærfyll >2 sek\n• Uro og angst\n\nSene tegn (dekompensert):\n• Hypotensjon – BT <90 systolisk\n• Forvirring / bevissthetspåvirkning\n\nBehandling:\n1. Behandle årsaken\n2. Legg flat – hev bena (unntak: hode/bekken/hjerte)\n3. Hold varm\n4. Ring 113\n\nNB: Betablokkere maskerer takykardi!",sev:"d",rel:["hypovolemi","tamponade","tensjon","arytmi","anafylaksi","sepsis"]},
    gcs:              {name:"GCS – Glasgow Coma Scale",plain:"Bevissthetsskala 3–15",body:"Øyne (1–4) + Verbal (1–5) + Motorisk (1–6). Synkende GCS er alvorlig.",sev:"w",rel:["avpu","hodeskade","bevissth","pupiller"]},
    avpu:             {name:"AVPU",plain:"Rask bevissthetsskala",body:"A = Alert: våken. V = Voice: reagerer på stemme. P = Pain: kun smertereaksjon. U = Unresponsive: ingen respons.",sev:"w",rel:["gcs","bevissth","hypoglykemi"]},
    pupiller:         {name:"Pupillevurdering",plain:"Sjekk øynene",body:"Normal: like store, reagerer på lys. Ensidig vid og treig = økt intrakranialt trykk. Begge faste og vide = kritisk.",sev:"d",rel:["hodeskade","intrakranialt","gcs"]},
    bevissth:         {name:"Bevissthetspåvirkning",plain:"Redusert bevissthet",body:"Enhver grad er alvorlig inntil årsak er kjent. Sikre luftvei. Mål blodsukker.",sev:"d",rel:["gcs","avpu","hypoglykemi","hodeskade","overdose"]},
    hlr:              {name:"HLR 30:2",plain:"30 kompresjoner, 2 innblåsninger",body:"ERC/NRR-standard. 30 brystkompresjoner etterfulgt av 2 innblåsninger. Alene: kun kompresjoner er akseptabelt.",sev:"d",rel:["aed","agonalpust","hjertestans"]},
    kompresjonsdyp:   {name:"5–6 cm dybde",plain:"Kompresjonsdybde",body:"Minimum 5 cm, ikke over 6 cm. La brystet heve seg fullstendig mellom kompresjoner.",sev:"d",rel:["hlr","kompfrekvens"]},
    kompfrekvens:     {name:"100–120/min",plain:"Kompresjonshastighet",body:"Tilsvarer tempoet i 'Stayin' Alive'. Tell høyt for å holde tempo.",sev:"w",rel:["hlr","kompresjonsdyp"]},
    aed:              {name:"AED – hjertestarter",plain:"Automatisk ekstern defibrillator",body:"Analyserer rytmen og gir støt ved VF/VT. Fortsett HLR umiddelbart etter støt.",sev:"d",rel:["hlr","hjertestans","arytmi"]},
    agonalpust:       {name:"Agonal pust",plain:"Gisp rett etter hjertestans",body:"Uregelmessig snorkende pust de første minuttene etter hjertestans. IKKE normal pust – start HLR.",sev:"d",rel:["hjertestans","hlr","luftvei"]},
    hosteoppfordring: {name:"Oppmuntre til hosting",plain:"",body:"Første tiltak ved delvis luftveisblokk. Kraftig hosting kan løsne fremmedlegeme.",sev:"w",rel:["ryggslagg","heimlich","luftvei"]},
    ryggslagg:        {name:"5 ryggslag",plain:"Slag mellom skulderbladene",body:"Bøy pasienten forover. Gi 5 kraftige slag med flat hånd mellom skulderbladene.",sev:"d",rel:["heimlich","hosteoppfordring","luftvei"]},
    heimlich:         {name:"Heimlich-manøver",plain:"Abdominale støt",body:"Stå bak pasienten. Knytt hånden under navlen. 5 kraftige støt innover og oppover.",sev:"d",rel:["ryggslagg","hosteoppfordring","luftvei"]},
    drukning:         {name:"Drukning – 5 innblåsninger",plain:"Start med pust ved drukning",body:"NRR: gi 5 innledende innblåsninger før kompresjoner. Kald drukning: fortsett HLR selv etter lang tid.",sev:"d",rel:["hlr","hypotermi","hypoxi"]},
    hypoxi:           {name:"Hypoksi",plain:"For lite oksygen",body:"Luftveisobstruksjon, drukning eller inhalasjonsskade. Behandling: åpen luftvei, oksygen.",sev:"d",rel:["luftvei","hjertestans","co","blastlung"]},
    hypovolemi:       {name:"Hypovolemi",plain:"For lite blod i kroppen",body:"Blødning eller væsketap. Stopp blødning, gi væske.",sev:"d",rel:["sjokk","bekken","femur","miltruptur"]},
    hypokalemi:       {name:"Hypo/hyperkalemi",plain:"Forstyrrelser i kaliumnivå",body:"Elektrolyttforstyrrelse kan utløse dødelig arytmi.",sev:"w",rel:["arytmi","hjertestans"]},
    tamponade:        {name:"Hjertetamponade",plain:"Blod trykker rundt hjertet",body:"Blod samler seg i hjertesekken og komprimerer hjertet.\n\nBecks triade:\n• Hypotensjon\n• Distenderte halsvener\n• Dempede hjertelyder\n\nBehandling: nåledrenasje på sykehus. I felt: ring 113, legg ned, rask transport.",sev:"d",rel:["hjerteskade","sjokk","hjertestans","tensjon"]},
    tensjon:          {name:"Tensjonspneumothorax",plain:"Luft bygger trykk i brysthulen",body:"Presser hjertet til frisk side. Dyspné, fraværende pustelyd, hypotensjon, trakeal deviasjon.\n\nNåldekompresjonen umiddelbart:\n① 2. IKR, midklavikulærlinje\n② 4.–5. IKR, fremre aksillærlinje\n\nNål over ribbeinkanten. Ikke vent på røntgen.",sev:"d",rel:["pneumothorax","tamponade","sjokk","hjertestans"]},
    trombose:         {name:"Trombose",plain:"Blodpropp i lunge eller hjerte",body:"Massiv lungeemboli eller STEMI kan gi hjertestans.",sev:"d",rel:["infarkt","hjertestans","sjokk"]},
    toksiner:         {name:"Toksiner / forgiftning",plain:"",body:"Overdose, CO, cyanid. Behandling avhenger av agens.",sev:"d",rel:["co","overdose","hjertestans"]},
    infarkt:          {name:"Hjerteinfarkt",plain:"Blodpropp i hjertekaret",body:"Trykkende brystsmerter >20 min, utstråling til venstre arm/kjeve/rygg, svette, kvalme. Ring 113.",sev:"d",rel:["hjertestans","arytmi","sjokk","trombose"]},
    fast:             {name:"FAST – slagscreening",plain:"Rask slagtest",body:"F: Ansiktshenge. A: Armsvakhet. S: Taleforstyrrelse. T: Tid – ring 113. Trombolyse-vindu 4,5 timer.",sev:"d",rel:["bevissth","gcs","hodeskade","nihss_tip"]},
    astma:            {name:"Astmaanfall",plain:"Luftveiene trekker seg sammen",body:"Piping i utpust. Alvorlig: kan ikke snakke setninger. Kritisk: stille thorax. Bronkodilator, ring 113.",sev:"w",rel:["luftvei","anafylaksi","pneumothorax"]},
    anafylaksi:       {name:"Anafylaksi",plain:"Livstruende allergisk reaksjon",body:"Elveblest + luftveissymptomer eller hypotensjon. Adrenalin 0,5 mg i.m. ytre lår (EpiPen). Ring 113.",sev:"d",rel:["luftveisoedem","sjokk","arytmi"]},
    ribbeinsbrudd:    {name:"Ribbeinsbrudd",plain:"Et eller flere ribbein er brutt",body:"Gir smertefull pusting. Fare for pneumothorax. Tre eller flere = flail chest.",sev:"w",rel:["pneumothorax","hemothorax","lungekont"]},
    rabdomyolyse:     {name:"Rabdomyolyse",plain:"Muskelceller brytes ned",body:"Cola-farget urin, nyresvikt. Ved langvarig klemskade.",sev:"d",rel:["crush","compartment"]},
    compartment:      {name:"Compartment-syndrom",plain:"Trykk i muskelfascier",body:"Økt trykk stenger av blodsirkulasjonen. Intens smerte, blek og kald ekstremitet. Kirurgisk nødsituasjon.",sev:"d",rel:["crush","rabdomyolyse","tibia","femur"]},
    koagulopati:      {name:"Koagulopati",plain:"Nedsatt evne til å danne blodpropp",body:"Forverres av hypotermi og acidose – den dødelige triaden.",sev:"d",rel:["hypotermi","sjokk","antikoag"]},
    sepsis:           {name:"Sepsis",plain:"Livstruende infeksjon i blodet",body:"Feber eller hypotermi, rask puls, rask pust, forvirring. Distributivt sjokk.",sev:"d",rel:["sjokk","bevissth","arytmi"]},
    ryggmargsjokk:    {name:"Nevrogent sjokk",plain:"Sjokk fra ryggmargsskade",body:"Hypotensjon og bradykardi (ikke takykardi). Varm hud under skadenivå.",sev:"d",rel:["columna","cervikalcolumna","sjokk"]},
    rus_maskerer:     {name:"Rus maskerer skade",plain:"Rusmidler skjuler tegn på skade",body:"Smertedempende effekt skjuler indre skader. Agitasjon kan skyldes hodeskade, hypoglykemi eller hypoksi. Alltid ABCDE.",sev:"d",rel:["hodeskade","hypoglykemi","bevissth","sjokk"]},
    alkohol:          {name:"Alkoholforgiftning",plain:"",body:"0,5–1,5 promille: koordinasjonssvikt. 2–3 promille: alvorlig, aspirasjonfare. Over 3 promille: bevisstløshet, livstruende.",sev:"w",rel:["aspirasjon","respirasjonsdep","hypoglykemi","hypotermi"]},
    aspirasjon:       {name:"Aspirasjon",plain:"Innånding av mageinnhold",body:"Oppkast som trekkes ned i luftveiene. Sideleie er det viktigste forebyggende tiltaket.",sev:"d",rel:["luftvei","respirasjonsdep","bevissth"]},
    nalokson:         {name:"Nalokson",plain:"Motgift mot opioider",body:"Dose: 0,4–0,8 mg i.m. (intramuskulært) eller 1–2 mg intranasalt. Virkningstid kortere enn de fleste opioider – pasienten kan falle tilbake i overdose etter 30–90 min. Overvåk kontinuerlig. Fentanyl kan kreve gjentatte doser.",sev:"d",rel:["opioidtriade","respirasjonsdep","luftvei"]},
    opioidtriade:     {name:"Opioid triade",plain:"Tre klassiske overdosetegn",body:"1. Respirasjonsdepresjon. 2. Bevisstløshet. 3. Nålespisse pupiller. Alle tre = opioidoverdose. Behandling: Nalokson + luftvei.",sev:"d",rel:["nalokson","miosepupiller","respirasjonsdep","luftvei"]},
    miosepupiller:    {name:"Miose",plain:"Nålespisse / trange pupiller",body:"Tyder på opioidpåvirkning, benzodiazepiner eller pontint slag.",sev:"w",rel:["opioidtriade","vidpupiller","pupiller"]},
    vidpupiller:      {name:"Mydriasis",plain:"Vide / store pupiller",body:"Stimulantpåvirkning (amfetamin, kokain, MDMA), hallusinogener, eller alvorlig hypoksi. Ensidig vid pupill = intrakranialt trykk.",sev:"w",rel:["miosepupiller","pupiller","stimulanter"]},
    stimulanter:      {name:"Stimulantpåvirkning",plain:"Amfetamin, kokain, MDMA",body:"Agitasjon, takykardi, hypertensjon, hypertermi, vide pupiller. Kan utløse hjertearytmi.",sev:"w",rel:["arytmi","infarkt","hypertermi_rus","hyponatremi"]},
    hypertermi_rus:   {name:"Rusrelatert hypertermi",plain:"Farlig overoppheting fra rus",body:"MDMA + fysisk aktivitet + varme kan gi kjernetemperatur over 40–42°C. Avkjøl aktivt.",sev:"d",rel:["varmeslag","hyponatremi","arytmi"]},
    ghb:              {name:"GHB-forgiftning",plain:"Brå bevisstløshet fra GHB",body:"Smal terapeutisk margin – liten ekstra dose kan gi bevisstløshet.",sev:"d",rel:["aspirasjon","respirasjonsdep","luftvei","bevissth"]},
    ketaminhole:      {name:"K-hole",plain:"Dyp dissosiert tilstand av ketamin",body:"Pasienten ser tilsynelatende våken ut men er ikke tilstede. Varer 15–45 min. Høy dose kan gi respirasjonsdepresjon.",sev:"d",rel:["respirasjonsdep","bevissth","luftvei"]},
    degloving:        {name:"Degloving",plain:"Huden rives av fra underliggende vev",body:"Typisk ved motorsykkelulykker. Stor infeksjonsrisiko. Dekk med sterilt bandasje.",sev:"w",rel:["sjokk"]},
    aeiou_a:          {name:"A – Alkohol / Acidose",plain:"",body:"Alkohol: demper CNS, kan gi bevisstløshet, hypotermi og hypoglykemi.\n\nAcidose: for mye syre i blodet. Ved traume: oksygenmangel til cellene → melkesyre. Forverrer koagulasjonen.",sev:"w",rel:["alkohol","hypoglykemi","koagulopati"]},
    aeiou_e:          {name:"E – Epilepsi",plain:"",body:"Etter anfall er pasienten ofte bevisstløs eller forvirret (postiktal fase). Varer minutter til over en time. Ligner hodeskade eller rus.",sev:"w",rel:["epilepsi","hodeskade","bevissth"]},
    aeiou_i1:         {name:"I – Insulin (hypoglykemi)",plain:"",body:"For lavt blodsukker (<4 mmol/L) er vanligste behandlbare årsak til nedsatt bevissthet. Mål alltid blodsukker.",sev:"d",rel:["hypoglykemi","bevissth"]},
    aeiou_o:          {name:"O – Overdose",plain:"",body:"• Opioider: trang pupill, langsom pust\n• Benzodiazepiner: sløvhet, koordinasjonssvikt\n• Alkohol: koordinasjonssvikt, aspirasjonfare\n\nVurder nalokson ved mistanke om opioidoverdose.",sev:"d",rel:["overdose","nalokson","respirasjonsdep","miosepupiller"]},
    aeiou_u:          {name:"U – Uremi",plain:"Avfallsstoffer hoper seg opp i blodet",body:"Uremi ved nyresvikt gir gradvis bevissthetspåvirkning, kløe, kvalme og kramper. Vanlig hos dialysepasienter.",sev:"w",rel:["bevissth","sepsis"]},
    aeiou_t:          {name:"T – Traume",plain:"",body:"Hodeskade kan gi direkte hjerneskade, blødning eller økt intrakranialt trykk.\n\nViktig: traume kan maskeres av rus, og rus kan etterligne hodeskade.",sev:"d",rel:["hodeskade","subduralt","intrakranialt","gcs","rus_maskerer"]},
    aeiou_i2:         {name:"I – Infeksjon (sepsis)",plain:"",body:"Alvorlig infeksjon kan gi septisk sjokk med bevissthetspåvirkning. Tegn: feber/hypotermi, rask puls, rask pust, forvirring.",sev:"d",rel:["sepsis","sjokk","bevissth"]},
    aeiou_p:          {name:"P – Psykiatri / Slag",plain:"",body:"Hjerneslag: plutselig bevissthetspåvirkning, ansiktshenge, armsvakhet, taleforstyrrelse. Bruk FAST.\n\nPsykiatrisk: utelukkelsesdiagnose – vurder alltid somatiske årsaker først.",sev:"d",rel:["fast","bevissth","hodeskade"]},
    infarkt_kvinner:  {name:"Hjerteinfarkt hos kvinner – atypisk",plain:"Kvinner har ofte andre symptomer enn menn",body:"Klassiske brystsmerter mangler oftere hos kvinner. Vanlige atypiske tegn:\n• Uttalt tretthet / utmattelse\n• Kvalme og oppkast\n• Smerter i rygg, nakke, kjeve eller skulder\n• Kortpustethet uten brystsmerter\n• Svimmelhet\n\nRisikofaktorer hos kvinner: menopause, diabetes og røyking gir høy risiko. Ring 113 ved mistanke – ikke vent på klassiske tegn.",sev:"d",rel:["infarkt","arytmi","sjokk"]},
    ektopisk:         {name:"Ektopisk graviditet",plain:"Fosteret fester seg utenfor livmoren",body:"Fosteret fester seg i egglederen i stedet for livmoren. Kan gi livstruende indre blødning ved ruptur.\n\nTegn: ensidig underlivssmerter, vaginalblødning, skuldersmerter (blod irriterer mellomgulvet). Kollaps.\n\nMistenk ved: kvinne i fruktbar alder + akutt abdomen + sjokk. Ring 113.",sev:"d",rel:["sjokk","hypovolemi","abruptio"]},
    ovariecyste:      {name:"Ovariecyste / torsjon",plain:"Cystisk blære eller vridd eggstokk",body:"Ovarietorsjon (vridd eggstokk): plutselig intens ensidig underlivssmerter, kvalme og oppkast. Kirurgisk nødsituasjon.\n\nRuptert cyste: akutte smerter, kan gi intern blødning. Ikke alltid synlig ytre skade.",sev:"d",rel:["ektopisk","sjokk","abdomen_distensjon"]},
    trombose_kvinner: {name:"DVT / lungeemboli – økt risiko",plain:"Blodpropp i ben eller lunge",body:"Økt risiko ved: p-piller (særlig kombinert med røyking), graviditet og postpartum, immobilisering.\n\nDVT: hevelse, varme og smerter i legg. Lungeemboli: plutselig dyspné, brystsmerter, takykardi. Kan gi hjertestans.",sev:"d",rel:["trombose","sjokk","takykardi"]},
    osteoporose_kvinner:{name:"Osteoporose hos kvinner",plain:"Redusert bentetthet – lettere å brekke",body:"Postmenopausale kvinner har økt risiko for osteoporose. Konsekvens: lavenergi-MOI kan gi alvorlige frakturer.\n\nSpesielt: hoftebrudd ved fall fra stående, kompresjonsbrudd i ryggraden, håndleddsbrudd. Mistenk fraktur ved lavere terskel enn hos menn.",sev:"w",rel:["hofte","columna","handledd","antikoag"]},
    kastefenomen:     {name:"Kastefenomen",plain:"Kroppen kastes ved elektrisk støt eller eksplosjon",body:"Ved elektrisk støt kan musklene krampe ukontrollert og kaste pasienten flere meter. Gir sekundærskader som ved høyenergi-fall: hodeskade, columna, thorax, bekken. Undersøk som høyenergi-MOI.",sev:"d",rel:["hodeskade","cervikalcolumna","thorax","columna"]},
    el_skade:         {name:"Elektrisk inn-/utgangssår",plain:"Strømbanen gjennom kroppen",body:"Inngangssår er lite og kan se uskyldig ut. Utgangssår er ofte større. Skaden langs strømbanen er langt mer alvorlig enn hudskaden indikerer. Dokumenter begge steder. Mistenk indre skade.",sev:"w",rel:["arytmi","brannskade","rabdomyolyse"]},
    el_sikkerhet:     {name:"Elektrisk skade – egensikkerhet",plain:"Ikke nærme deg før strøm er brutt",body:"En strømførende pasient er farlig å berøre. Tiltak: varsle el-verk / 110, bruk isolert materiale til å flytte pasienten fra strømkilden, eller vent til strøm er brutt. Høyspent: hold minimum 10 meters avstand.",sev:"d",rel:["x_sikkerhet"]},
    muskelskade:      {name:"Muskelskade ved elektrisk støt",plain:"",body:"Elektrisk strøm kan gi alvorlig muskelskade langs strømbanen uten synlige ytre tegn. Kan utløse rabdomyolyse og nyresvikt. Cola-farget urin er et tegn.",sev:"w",rel:["rabdomyolyse","el_skade"]},
    brann_sikkerhet:  {name:"Brannsikkerhet – egensikkerhet",plain:"",body:"Aldri gå inn i et brennende bygg uten verneutstyr og opplæring. Røyk dreper raskere enn flammer. CO og cyanid gir bevistløshet på sekunder. Vent på brannvesenet.",sev:"d",rel:["co","cyanid","x_sikkerhet"]},
    cyanid:           {name:"Cyanid­forgiftning",plain:"Giftig gass fra brennende plast",body:"Frigjøres ved forbrenning av mange plastmaterialer og møbler. Blokkerer cellenes evne til å bruke oksygen. Rask bevisstløshet. Behandling: frisk luft, antidot (hydroksykobalamin) på sykehus.",sev:"d",rel:["co","inhalasjon","bevissth"]},
    brannskade_kjoling:{name:"Kjøling av brannskade",plain:"Romtemperert vann i 20 minutter",body:"Kjøl med rennende romtemperert vann (ikke kaldt, ikke is) i 20 minutter. Ikke bruk is – gir fryseskade og forverrer vevsskaden. Ikke glasur, smør eller tannkrem. Etter kjøling: dekk med rent bandasje. OBS: hypotermirisiko ved store brannskader.",sev:"w",rel:["brannskade","hypotermi"]},
    forgiftning_hva:  {name:"Hva er inntatt?",plain:"",body:"Prøv å finne ut: hva (medikament, kjemikalie, rusmiddel), dose/mengde, tidspunkt for inntak, og om det er kombinasjon. Ta med emballasje til sykehuset. Ring Giftinfo (22 59 13 00) for spesifikke råd.",sev:"",rel:["ringGift","nalokson","co"]},
    drukning_barn:    {name:"Barn drukner stille",plain:"",body:"Barnedrukning gir sjelden den klassiske armbevegelsen og ropingen vi forventer. Barnet synker stille under vann. Hold øye med barn nær vann kontinuerlig – ikke kun «kikke innimellom».",sev:"d",rel:["drukning","hypoxi","hypotermi"]},
    drukning_sek:     {name:"Akutt lungeødem etter drukning",plain:"Forsinket respirasjonssvikt etter drukning",body:"Timer etter drukning kan det oppstå akutt lungeødem og respirasjonssvikt – selv etter tilsynelatende ukomplisert redning. Tidligere kalt 'sekundærdrukting'. Alle drukningspasienter bør observeres på sykehus minimum 6–24 timer. Tegn: tiltakende dyspné, hoste, cyanose.",sev:"d",rel:["drukning","inhalasjon","pneumothorax"]},
    drukning_hypotermi:{name:"Kald drukning og hypotermi",plain:"Hypotermi ved drukning – ikke alltid fienden",body:"Kaldt vann (<15°C) kan kjøle ned hjernen raskt og redusere oksygenbehovet. Overlevelse er rapportert etter lang tid under vann i kaldt vann.\n\nPrinsipp: 'Ikke død før varm og død'\n• Fortsett HLR frem til pasienten er varmet opp\n• Hypotermi beskytter, men gir også arytmi og stiv brystkasse\n• Håndter forsiktig – kalde hjerter er sensitive\n\nForskjell fra varmtvann-drukning: varmtvann gir raskere hjerneskade.",sev:"d",rel:["drukning","hypotermi","hlr","arytmi"]},
    hypotermi_mild:   {name:"Mild hypotermi (over 32°C)",plain:"",body:"Kjernetemperatur 32–35°C. Tegn: intens skjelving, klumsete bevegelser, nedsatt koordinasjon, kald hud. Pasienten er bevisst. Tiltak: flytt inn fra kulde, fjern våte klær, gi varm drikke hvis bevisst, space blanket.",sev:"w",rel:["hypotermi","frostskader"]},
    hypotermi_mod:    {name:"Moderat hypotermi (28–32°C)",plain:"",body:"Tegn: slutter å skjelve (farlig tegn!), tiltakende forvirring og sløvhet, stiv muskulatur, langsom puls. Tiltak: som mild + varsle AMK, håndter forsiktig (arytmirisiko), ikke la pasienten gå.",sev:"d",rel:["hypotermi","arytmi","hypotermi_mild"]},
    brudd_sikre:      {name:"Sikre bruddtegn",plain:"Disse bekrefter brudd",body:"• Unormal stilling eller vinkling av lemmet\n• Krepitasjon – knitrende lyd/følelse ved bevegelse\n• Synlig bein (åpent brudd)\n• Unormal bevegelse der det ikke skal være bevegelse\n\nEtt eller flere av disse = brudd bekreftet. Stabiliser og transport.",sev:"d",rel:["brudd_tiltak","brudd_usikre"]},
    brudd_usikre:     {name:"Usikre bruddtegn",plain:"Disse kan skyldes brudd – men ikke sikkert",body:"• Smerte og ømhet over knokkelen\n• Hevelse og blåmerker\n• Nedsatt funksjon / bevegelsesevne\n• Økt varme\n\nUsikre tegn alene utelukker ikke brudd. Behandle som brudd ved tvil.",sev:"w",rel:["brudd_sikre","brudd_tiltak"]},
    brudd_tiltak:     {name:"Tiltak ved brudd",plain:"",body:"1. Stabiliser i funnet stilling – aldri forsøk å rette ut\n2. Sjekk puls og sensibilitet distalt for skaden\n3. Immobiliser med det du har (skinner, puter, bandasje)\n4. Åpent brudd: dekk med sterilt bandasje, ikke trykk inn bein\n5. Transport til sykehus",sev:"w",rel:["puls_distalt","brudd_aapent","brudd_sikre"]},
    brudd_aapent:     {name:"Åpent brudd",plain:"Bein stikker ut eller kommuniserer med huden",body:"Høy infeksjonsrisiko. Tiltak: dekk med sterilt bandasje fuktet med NaCl eller rent vann. Ikke trykk bein tilbake. Ikke fjern fremmedlegemer. Rask transport til sykehus.",sev:"d",rel:["brudd_tiltak","infeksjon_risiko"]},
    inhalasjon_tegn:  {name:"Tegn på inhalasjonsskade",plain:"",body:"• Sot rundt munn og nese\n• Sottilblandet spytt\n• Svidde nesehår\n• Brannskader i munnhule\n• Heshet og hoste\n• Hovne lepper\n\nAlvorlig luftveisskade kan gi behov for tidlig intubasjon. Prioriter rask transport.",sev:"d",rel:["inhalasjon","luftveisoedem","stridor","luftvei"]},
    brannskade_dekk:  {name:"Dekking av brannskade",plain:"",body:"Plastfilm (gladpack) direkte mot brannskaden etter kjøling – ikke sirkulært rundt lemmet. Deretter tørre håndklær eller tepper utenpå for å hindre varmetap. Ikke bomullstøy direkte mot sår.",sev:"w",rel:["brannskade","hypotermi"]},
    brannskade_innlegg:{name:"Innleggelse ved brannskade",plain:"",body:"Innlegg ved:\n• Over 5% kroppsoverflate (voksen)\n• Over 10% hos barn\n• All 3. grad\n• Ansikt, hender, føtter, genitalia\n• Mistenkt inhalasjonsskade\n• Høyspentskade\n\nStore skader (>15% voksen / >10% barn) = traumemottak.",sev:"d",rel:["brannskade","inhalasjon_tegn","el_skade"]},
    infeksjon_risiko: {name:"Infeksjonsrisiko ved åpent brudd",plain:"",body:"Åpent brudd gir direkte kommunikasjon mellom bein og omgivelsene. Høy risiko for osteomyelitt (beininfeksjon). Dekk sterilt, transport raskt. Antibiotika og kirurgi på sykehus.",sev:"d",rel:["brudd_aapent"]},
    aeiou_s:          {name:"S – Sjokk / Stroke",plain:"",body:"Sjokk: utilstrekkelig blodforsyning til hjernen gir bevissthetspåvirkning.\n\nStroke (slag): akutt forstyrrelse i hjernens blodtilførsel.",sev:"d",rel:["sjokk","fast","bevissth"]},
    /* ── Barne HLR ── */
    hlr_barn:         {name:"HLR barn – én hånd",plain:"For større barn (ca. 1–8 år)",body:"Bruk én hånd for barn som er for store for 2-fingerteknikk men for små for to hender. Legg hælen av én hånd midt på brystet (nedre halvdel av brystbeinet). Hold armen rett. Komprimer 1/3 av brystkassens dybde.\n\nSpedbarn (<1 år): 2 fingre på midten av brystet, like under brystvortene.",sev:"d",rel:["hlr","hlr_barn_dybde","aed"]},
    hlr_barn_dybde:   {name:"Kompresjonsdybde barn",plain:"1/3 av brystkassens dybde",body:"Komprimer 1/3 av brystkassens dybde:\n• Spedbarn (<1 år): ca. 4 cm\n• Barn 1–8 år: ca. 5 cm\n• Større barn/voksen: 5–6 cm\n\nSame ratio: 30:2. Innblåsning: pust til brystet hever seg synlig – ikke mer.",sev:"d",rel:["hlr","hlr_barn","kompresjonsdyp"]},
    /* ── Øyeskade ── */
    oye_impalement:   {name:"Impalert gjenstand i øyet",plain:"Gjennomboret øye",body:"ALDRI fjern en gjenstand som stikker inn i øyet – dette kan forverre skaden og føre til tap av øyeinnholdet.\n\nTiltak:\n1. Dekk øyet med et beger, kopp eller improvisert skall\n2. Fest forsiktig rundt øyet – IKKE trykk mot øyet\n3. Dekk BEGGE øyne (urolige øyne beveger seg sammen)\n4. Transport til sykehus",sev:"d",rel:["ansiktsfraktur","hodeskade"]},
    oye_kjemisk:      {name:"Kjemisk sprut i øyet",plain:"",body:"UMIDDELBAR skylling er avgjørende:\n1. Skyll med rikelig rennende vann i minst 10–15 min\n2. Hold øyelokket åpent med fingrene\n3. Skyll fra indre hjørne (neseside) utover\n4. Fjern kontaktlinse hvis enkelt\n5. Ring 113 eller oppsøk lege\n\nSyre vs. base: baser (lut, ammoniakk) gir dypere skade og krever lengre skylling (30 min).",sev:"d",rel:[]},
    oye_saar:         {name:"Perforerende øyesår",plain:"",body:"Dekk med sterilt bandasje. IKKE trykk mot øyet. Transport til sykehus.",sev:"w",rel:["oye_impalement"]},
    oye_kontusjon:    {name:"Stump øyeskade",plain:"Slag mot øyet",body:"Is mot kinnbenet rundt øyet – aldri direkte press mot selve øyeeplet. Ring lege ved synsforstyrrelser, blødning i øyet eller kraftig smerte.",sev:"w",rel:[]},
    /* ── Fødsel ── */
    fodsel_transport: {name:"Ikke transport ved nært forestående fødsel",plain:"",body:"Ikke flytt mor dersom:\n• Hodet er synlig (crowning)\n• Sterk trang til å presse – ikke kan stoppe\n• Tid mellom veer <2 min\n• Barnet er på vei\n\nRing 113 – AMK kan veilede gjennom fødselen. Forbered varmt underlag og tepper til barnet.",sev:"d",rel:["fodsel_hode","fodsel_navlesnor"]},
    fodsel_hode:      {name:"Fødsel – støtte av hodet",plain:"",body:"Når hodet kommer:\n1. Støtt hodet forsiktig med begge hender\n2. IKKE hold igjen eller press mot – la det komme naturlig\n3. Sjekk om navlesnoren er rundt halsen\n4. La skuldrene rotere naturlig – øvre skulder kommer først\n5. Hold barnet støttende – det er glatt!\n6. Tørk og varm umiddelbart – dekk med teppe\n\nOppgi fødselstidspunkt til AMK.",sev:"d",rel:["fodsel_navlesnor","fodsel_skulder","fodsel_transport"]},
    fodsel_navlesnor: {name:"Navlesnor rundt halsen",plain:"",body:"Kjenn forsiktig om navlesnoren er rundt barnets hals etter at hodet er født.\n\nLøs snor: skyv forsiktig over hodet.\nStram snor: klyp av med to klemmer (eller knyt to knuter) og klipp mellom dem.\n\nNavlesnoren behøver ikke klippes med en gang – vent gjerne til AMK/helsepersonell.",sev:"d",rel:["fodsel_hode","fodsel_transport"]},
    fodsel_skulder:   {name:"Skulder macrosom",plain:"Skulderen setter seg fast",body:"Tegn: hodet er født men kroppen kommer ikke. Ikke trekk i hodet!\n\nTiltak:\n1. McRoberts-stilling: legg mor på rygg, bøy knærne helt opp mot brystet (hyper-fleksjon)\n2. Suprapubisk press: en assistent presser ned og bakover over skambenet – IKKE press på mors mage\n3. Ring 113 – dette er en akutt obstetrikk-situasjon",sev:"d",rel:["fodsel_hode","fodsel_transport"]}
  };
